import hashlib
import hmac
import os
import re
import time
from typing import Optional, Tuple, Dict


class UserStore:
    """Persistent user credential store."""

    # Valid roles that may be assigned at registration time.
    VALID_ROLES = {'user', 'moderator', 'admin', 'superadmin'}

    def __init__(self):
        self._users: Dict[str, dict] = {}
        self._failed_attempts: Dict[str, list] = {}
        self._lockout_duration = 300  # 5 minutes
        self._max_attempts = 5

    def _canonicalize_username(self, username: str) -> str:
        """Canonicalize username to lowercase ASCII.

        Only ASCII alphanumeric and underscore are permitted,
        so no Unicode normalization is needed - we reject
        non-ASCII at the validation stage.
        """
        return username.strip().lower()

    def _hash_password(self, password: str, salt: bytes) -> bytes:
        """Derive key using PBKDF2-HMAC-SHA256."""
        return hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt,
            iterations=100000
        )

    def _validate_username(self, username: str) -> bool:
        """Strictly validate username: ASCII alphanumeric and underscore only."""
        if not username or len(username) < 3 or len(username) > 32:
            return False
        # Reject ANY character outside ASCII alphanumeric + underscore
        for ch in username:
            if ch not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_':
                return False
        return True

    def register_user(self, username: str, password: str, role: str = 'user') -> bool:
        """Register a new user with validated username."""
        if not username or not password:
            return False

        if len(password) < 8:
            return False

        # Validate role against the known set of valid roles
        if role not in self.VALID_ROLES:
            return False

        # Strict ASCII-only validation BEFORE any processing
        if not self._validate_username(username):
            return False

        canonical = self._canonicalize_username(username)

        if canonical in self._users:
            return False

        salt = os.urandom(32)
        password_hash = self._hash_password(password, salt)

        self._users[canonical] = {
            'password_hash': password_hash,
            'salt': salt,
            'role': role,
            'created_at': time.time(),
            'original_username': username
        }
        return True

    def _check_lockout(self, username: str) -> bool:
        """Check if account is locked out. Returns True if locked."""
        canonical = self._canonicalize_username(username)
        if canonical not in self._failed_attempts:
            return False

        attempts = self._failed_attempts[canonical]
        # Clean old attempts
        cutoff = time.time() - self._lockout_duration
        attempts = [t for t in attempts if t > cutoff]
        self._failed_attempts[canonical] = attempts

        return len(attempts) >= self._max_attempts

    def _record_failure(self, username: str):
        """Record a failed authentication attempt."""
        canonical = self._canonicalize_username(username)
        if canonical not in self._failed_attempts:
            self._failed_attempts[canonical] = []
        self._failed_attempts[canonical].append(time.time())

    def authenticate(self, username: str, password: str) -> Tuple[bool, Optional[str]]:
        """Authenticate user credentials.

        Returns (success, role) tuple.
        """
        if not username or not password:
            return False, None

        # Validate format before any lookup
        if not self._validate_username(username):
            return False, None

        if self._check_lockout(username):
            return False, None

        canonical = self._canonicalize_username(username)

        if canonical not in self._users:
            # Perform dummy hash to prevent timing oracle
            self._hash_password(password, os.urandom(32))
            self._record_failure(username)
            return False, None

        user = self._users[canonical]
        computed_hash = self._hash_password(password, user['salt'])

        if not hmac.compare_digest(computed_hash, user['password_hash']):
            self._record_failure(username)
            return False, None

        # Clear failed attempts on success
        if canonical in self._failed_attempts:
            del self._failed_attempts[canonical]

        return True, user['role']


class AccessController:
    """Role-based access control with privilege escalation protection."""

    ROLE_HIERARCHY = {
        'user': 0,
        'moderator': 1,
        'admin': 2,
        'superadmin': 3
    }

    PROTECTED_RESOURCES = {
        '/admin/users': 'admin',
        '/admin/config': 'superadmin',
        '/admin/logs': 'moderator',
        '/api/data': 'user'
    }

    def __init__(self, user_store: UserStore):
        self._store = user_store
        secret = os.environ.get('SESSION_SECRET', '')
        if not secret or len(secret) < 32:
            raise ValueError("SESSION_SECRET must be at least 32 characters")
        self._session_secret = secret.encode('utf-8')

    def _generate_session_token(self, username: str, role: str) -> str:
        """Generate a signed session token."""
        timestamp = str(int(time.time()))
        payload = f"{username}|{role}|{timestamp}"
        signature = hmac.new(
            self._session_secret,
            payload.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()
        return f"{payload}|{signature}"

    def _verify_session_token(self, token: str) -> Optional[dict]:
        """Verify and parse a session token."""
        parts = token.rsplit('|', 1)
        if len(parts) != 2:
            return None

        payload, provided_sig = parts
        expected_sig = hmac.new(
            self._session_secret,
            payload.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(provided_sig, expected_sig):
            return None

        payload_parts = payload.split('|')
        if len(payload_parts) != 3:
            return None

        username, role, timestamp = payload_parts

        # Validate role is known
        if role not in self.ROLE_HIERARCHY:
            return None

        # Check session age (max 1 hour)
        try:
            created = int(timestamp)
        except ValueError:
            return None

        if time.time() - created > 3600:
            return None

        # Validate username format
        if not self._store._validate_username(username):
            return None

        return {'username': username, 'role': role, 'created': created}

    def login(self, username: str, password: str) -> Optional[str]:
        """Authenticate and create session."""
        success, role = self._store.authenticate(username, password)
        if not success:
            return None

        token = self._generate_session_token(username, role)
        return token

    def check_access(self, token: str, resource: str) -> bool:
        """Check if session has access to resource."""
        session = self._verify_session_token(token)
        if session is None:
            return False

        required_role = self.PROTECTED_RESOURCES.get(resource)
        if required_role is None:
            return False

        user_level = self.ROLE_HIERARCHY.get(session['role'], -1)
        required_level = self.ROLE_HIERARCHY.get(required_role, 999)

        return user_level >= required_level

    def change_role(self, admin_token: str, target_username: str, new_role: str) -> bool:
        """Allow superadmin to change user roles."""
        session = self._verify_session_token(admin_token)
        if session is None:
            return False

        # Only superadmin can change roles
        if session['role'] != 'superadmin':
            return False

        if new_role not in self.ROLE_HIERARCHY:
            return False

        # Cannot escalate to superadmin
        if new_role == 'superadmin':
            return False

        # Validate and canonicalize target
        if not self._store._validate_username(target_username):
            return False

        canonical_target = self._store._canonicalize_username(target_username)

        if canonical_target not in self._store._users:
            return False

        self._store._users[canonical_target]['role'] = new_role
        return True


def create_application():
    """Initialize the application with default admin account."""
    store = UserStore()

    admin_pass = os.environ.get('ADMIN_PASSWORD', '')
    if not admin_pass or len(admin_pass) < 12:
        raise ValueError("ADMIN_PASSWORD must be at least 12 characters")

    store.register_user('admin', admin_pass, 'superadmin')

    controller = AccessController(store)
    return store, controller
